(()=>{'use strict';const $=id=>document.getElementById(id),labels={open:'Offen',progress:'In Bearbeitung',done:'Erledigt',na:'Entfällt'};let state={version:1,process:'onboarding',title:'',anchor:'',notes:'',tasks:window.NexusProcesses.seed('onboarding')},removed=[];
const changed=()=>document.dispatchEvent(new CustomEvent('nexus:content-changed'));
function summary(){const active=state.tasks.filter(t=>t.state!=='na'),done=active.filter(t=>t.state==='done').length;const today=new Date().toLocaleDateString('sv-SE');const overdue=active.filter(t=>t.due&&t.due<today&&t.state!=='done').length;$('checklistSummary').textContent=done+' von '+active.length+' aktiven Aufgaben erledigt'+(overdue?' · '+overdue+' überfällig':'');}
function field(title,kind,value,change){const label=document.createElement('label');label.textContent=title;const input=document.createElement(kind==='textarea'?'textarea':'input');if(kind!=='textarea')input.type=kind;input.value=value;input.addEventListener('input',()=>change(input.value));label.append(input);return label;}
function renderTasks(){const root=$('taskList'),filter=$('taskFilter').value;root.replaceChildren();const today=new Date().toLocaleDateString('sv-SE');for(const task of state.tasks.filter(t=>!filter||t.state===filter)){const card=document.createElement('article');card.className='ws-card task-card';card.dataset.state=task.state;const top=document.createElement('div');top.className='task-top';const h=document.createElement('strong');h.textContent=task.title;const del=document.createElement('button');del.type='button';del.textContent='Aufgabe entfernen';del.onclick=()=>{removed.push(task);state.tasks=state.tasks.filter(t=>t.id!==task.id);$('undoTask').hidden=false;renderTasks();summary();changed();};top.append(h,del);const grid=document.createElement('div');grid.className='task-fields';grid.append(field('Verantwortlich','text',task.owner,v=>{task.owner=v;changed();}),field('Fällig am','date',task.due,v=>{task.due=v;task.dueTouched=true;summary();changed();}));const label=document.createElement('label');label.textContent='Aufgabenstatus';const select=document.createElement('select');Object.entries(labels).forEach(([value,title])=>select.add(new Option(title,value)));select.value=task.state;select.onchange=()=>{task.state=select.value;card.dataset.state=task.state;summary();if($('taskFilter').value)renderTasks();changed();};label.append(select);grid.append(label);card.append(top,field('Aufgabe','text',task.title,v=>{task.title=v;h.textContent=v;changed();}),grid,field('Notiz / Ergebnis','textarea',task.note,v=>{task.note=v;changed();}));if(task.due&&task.due<today&&!['done','na'].includes(task.state)){const warning=document.createElement('p');warning.className='task-overdue';warning.textContent='Termin überschritten';card.append(warning);}if(['protokoll','exit','zeugnis','bewertung'].includes(task.link)){const a=document.createElement('a');a.href='./'+task.link+'.html';a.className='task-link';a.textContent='Passendes Werkzeug öffnen ↗';card.append(a);}root.append(card);}if(!root.children.length){const p=document.createElement('p');p.textContent='Keine Aufgaben für diesen Filter.';root.append(p);}}
function render(){$('processType').value=state.process;$('caseTitle').value=state.title;$('anchorDate').value=state.anchor;$('caseNotes').value=state.notes;$('anchorLabel').textContent=state.process==='offboarding'?'Letzter Arbeitstag':'Erster Arbeitstag';$('taskFilter').value='';renderTasks();summary();}
$('caseTitle').oninput=e=>{state.title=e.target.value;changed();};$('caseNotes').oninput=e=>{state.notes=e.target.value;changed();};$('anchorDate').onchange=e=>{state.anchor=e.target.value;state.tasks.forEach(t=>{if(!t.dueTouched&&typeof t.offset==='number')t.due=window.NexusProcesses.due(state.anchor,t.offset);});renderTasks();summary();changed();};$('taskFilter').onchange=renderTasks;
$('processType').onchange=e=>{const next=e.target.value;if(next===state.process)return;if(!confirm('Aufgaben durch die Vorlage für '+(next==='offboarding'?'Offboarding':'Onboarding')+' ersetzen? Der bisherige Vorgang kann vorher als Entwurf gespeichert werden.')){e.target.value=state.process;return;}state.process=next;state.tasks=window.NexusProcesses.seed(next,state.anchor);removed=[];$('undoTask').hidden=true;render();changed();};
$('addTask').onclick=()=>{state.tasks.push({id:crypto.randomUUID(),title:'Neue Aufgabe',owner:'',due:'',dueTouched:true,state:'open',note:'',link:''});$('taskFilter').value='';renderTasks();summary();changed();};$('undoTask').onclick=()=>{if(removed.length)state.tasks.push(removed.pop());$('undoTask').hidden=!removed.length;renderTasks();summary();changed();};
window.NexusModule={type:'checklisten',title:'Checkliste',titleFromData:()=>state.title,getData:()=>JSON.parse(JSON.stringify(state)),setData(d){if(d?.version!==1||!['onboarding','offboarding'].includes(d.process)||typeof d.title!=='string'||typeof d.anchor!=='string'||typeof d.notes!=='string'||!Array.isArray(d.tasks)||d.tasks.some(t=>typeof t.id!=='string'||typeof t.title!=='string'||typeof t.owner!=='string'||typeof t.due!=='string'||typeof t.note!=='string'||!Object.hasOwn(labels,t.state)))throw Error('Checklistenformat ist ungültig.');state=JSON.parse(JSON.stringify(d));removed=[];$('undoTask').hidden=true;render();},check(){const issues=[];if(!state.title.trim())issues.push({level:'error',text:'Vorgangstitel fehlt.'});if(!state.anchor)issues.push({level:'error',text:'Erster / letzter Arbeitstag fehlt.'});if(!state.tasks.length||state.tasks.some(t=>!t.title.trim()))issues.push({level:'error',text:'Aufgaben vollständig benennen.'});const open=state.tasks.filter(t=>t.state!=='na');if(open.some(t=>!t.owner.trim()||!t.due))issues.push({level:'warning',text:'Bei aktiven Aufgaben fehlen Verantwortliche oder Fälligkeiten.'});return issues;}};render();})();
